try{if(!document.documentElement.dataset.theme)document.documentElement.dataset.theme=localStorage.getItem('cp-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{document.documentElement.dataset.theme='light'}
const icons={arrow:'<path d="M4 10h12m-5-5 5 5-5 5"/>',external:'<path d="M12 3h5v5M17 3 8 12M8 4H4v13h13v-4"/>',search:'<circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/>',book:'<path d="M10 5C7 3 4 3 2 4v12c3-1 5-1 8 1 3-2 5-2 8-1V4c-3-1-5-1-8 1Zm0 0v12"/>',layers:'<path d="m10 2 8 4-8 4-8-4Zm-8 9 8 4 8-4M2 15l8 4 8-4"/>',branch:'<circle cx="5" cy="4" r="2"/><circle cx="15" cy="5" r="2"/><circle cx="5" cy="16" r="2"/><path d="M5 6v8m0-3c6 0 10-1 10-4"/>',file:'<path d="M12 2H4v16h12V6Zm0 0v5h4M7 11h6m-6 3h5"/>',code:'<path d="m6 5-4 5 4 5m8-10 4 5-4 5M12 3 8 17"/>',close:'<path d="m5 5 10 10M15 5 5 15"/>',menu:'<path d="M3 5h14M3 10h14M3 15h14"/>',sun:'<circle cx="10" cy="10" r="3.5"/><path d="M10 1v2m0 14v2M1 10h2m14 0h2M3.6 3.6 5 5m10 10 1.4 1.4m0-12.8L15 5M5 15l-1.4 1.4"/>',moon:'<path d="M17 12.5A7.5 7.5 0 0 1 7.5 3a7.5 7.5 0 1 0 9.5 9.5Z"/>',chevron:'<path d="m6 8 4 4 4-4"/>',copy:'<rect x="7" y="7" width="10" height="11" rx="1"/><path d="M13 7V2H2v11h5"/>',check:'<path d="m4 10 4 4 8-9"/>',globe:'<circle cx="10" cy="10" r="8"/><ellipse cx="10" cy="10" rx="3.5" ry="8"/><path d="M2 10h16"/>'};
