function recordTitle(r){return r.title;}
function recordPath(r){return r.route.replace(/^\/en\//,'').replace(/\/$/,'');}
function recordLabel(r){return t({paper:'papers',spec:'specs',study:'studies',glossary:'reference',bibliography:'reference',appendix:'appendices'}[r.kind]);}
function paperCategory(r){return r.category;}
function paperCard(r){
return `<article class="paper-card"><a href="${url(recordPath(r))}" class="paper-cover" aria-label="${esc(r.title)}">${cover(r)}<span class="cover-id">${recordLabel(r)}</span></a><div class="paper-content"><div class="metadata"><span>${t('publicationEdition')} ${esc(corpus.publication.edition)}</span><span>${t('englishText')}</span></div><h3><a href="${url(recordPath(r))}">${esc(r.title)}</a></h3><p lang="en">${esc(r.summary)}</p>${link(recordPath(r),t('readPaper'))}</div></article>`;
}
function home(){
const papers=corpus.records.filter(r=>r.kind==='paper'),specs=corpus.records.filter(r=>r.kind==='spec'),studies=corpus.records.filter(r=>r.kind==='study');
return `<section class="editorial-hero"><div class="hero-art-bg" aria-hidden="true"></div><div class="container hero-layout"><div class="hero-copy"><div class="eyebrow"><span class="tiny-diamond" aria-hidden="true"></span>${t('heroLabel')}</div><h1>${t('heroTitle')}</h1><p class="lead">${t('heroDesc')}</p><div class="actions">${link('research',t('readResearch'),'button')}${link('engineering',t('browseSpecs'))}</div><p class="hero-note">${t('heroNote')}</p></div></div></section>
<div class="container"><div class="release-strip"><span><span class="status-dot" aria-hidden="true"></span>${t('publicationEdition')} ${esc(corpus.publication.edition)}</span><a href="${url('research')}"><strong>${papers.length}</strong> ${t('papers')}</a><a href="${url('engineering/specifications')}"><strong>${specs.length}</strong> ${t('specs')}</a><a href="${url('engineering/studies')}"><strong>${studies.length}</strong> ${t('studies')}</a></div>
<section class="research-section" id="papers"><div class="section-heading"><div><h2>${t('releaseTitle')}</h2><p>${t('releaseDesc')}</p></div>${link('research',t('viewAllPapers'))}</div><div class="paper-grid">${[papers[0],papers[4],papers[6]].map(paperCard).join('')}</div><p class="research-caveat">${t('statusNote')}</p></section>
<section class="purpose-section" id="purpose"><div class="purpose-art">${cover({image:'knowledge-dialogue.webp'})}<span class="image-credit">${t('coverNote')}</span></div><div class="purpose-copy"><span class="section-kicker">Knowledge Contract Arcana</span><h2>${t('projectPurpose')}</h2><p>${t('purposeText')}</p><div class="publication-paths">${link('engineering',t('docs'))}${link('reference',t('reference'))}${link('appendices',t('appendices'))}</div></div></section>
<section class="journal-section"><div class="section-heading"><h2>${t('sourceArticles')}</h2>${link('journal',t('allEntries'))}</div><div class="journal-grid">${corpus.articles.map(journalCard).join('')}</div></section>
<section class="access-section" id="search"><div><span class="section-kicker">api.contract.place</span><h2>${t('publicSearch')}</h2><p>${t('publicSearchDesc')}</p><a class="button" href="${url('search')}#document-search">${t('openDocumentSearch')}${icon('arrow')}</a></div><div class="access-routes"><a href="${url('appendices/api-integration')}"><span>HTTP API</span><strong>/v1/search</strong>${icon('arrow')}</a><a href="${url('docs/availability')}"><span>Model Context Protocol</span><strong>/mcp</strong>${icon('arrow')}</a><p>${t('integrationDesc')}</p></div></section>
<section class="closing" id="use-and-cite"><div><h2>${t('openWork')}</h2><p>${t('licenseText')}</p></div>${link('about',t('licensing'),'button')}</section><details class="publication-snapshot"><summary>${t('publicationEdition')} ${esc(corpus.publication.edition)}</summary><p>${t('revision')}: <a href="https://github.com/Arcanada-one/knowledge-contract/tree/${corpus.publication.commit}"><code>${corpus.publication.commit}</code></a> · <a href="/publication.json">publication.json</a></p>${link('appendices/source-map',t('sourceMap'))}</details></div>`;
}
function research(){
const q=new URLSearchParams(location.search),type=q.get('type')||'all',query=q.get('q')||'';
return `<div class="container">${pageHead(t('research'),t('researchIntro'))}<p class="intro-note">${t('statusNote')}</p><div class="filter-bar">${['all','foundations','systems','evaluation'].map(x=>filterButton(x,t(x),type)).join('')}<input class="search-input" id="reference-search" type="search" placeholder="${t('findReference')}" aria-label="${t('findReference')}" value="${esc(query)}"></div><div id="reference-results">${referenceResults(type,query)}</div></div>`;
}
function referenceResults(type,query){
const all=corpus.records.filter(r=>r.kind==='paper'),items=all.filter(r=>(type==='all'||paperCategory(r)===type)&&normalize(r.title+' '+r.summary+' '+r.id).includes(normalize(query)));
return `<div class="result-count">${items.length} / ${all.length}</div><div class="paper-grid catalog-grid">${items.map(r=>paperCard(r).replace(/<(\/?)h3>/g,'<$1h2>')).join('')}</div>${items.length?'':`<div class="empty"><h2>${t('noResults')}</h2><button class="button" data-clear>${t('clear')}</button></div>`}`;
}
function publicationList(kinds,title,intro){
const records=corpus.records.filter(r=>kinds.includes(r.kind));
return `<div class="container">${pageHead(t(title),t(intro))}<div class="spec-list">${records.map(r=>`<a class="spec-row" href="${url(recordPath(r))}"><div class="card-icon">${icon('file')}</div><div><h2 lang="en">${esc(r.title)}</h2><p lang="en">${esc(r.summary)}</p><div class="metadata"><span>${recordLabel(r)}</span><span>${t('englishText')}</span></div></div>${icon('arrow')}</a>`).join('')}</div></div>`;
}
function engineering(){
return `<div class="container">${pageHead(t('docs'),t('engineeringIntro'))}<div class="publication-sections"><a class="record" href="${url('engineering/specifications')}"><div><h2>${t('specs')}</h2><p>${t('specIntro')}</p></div>${icon('arrow')}</a><a class="record" href="${url('engineering/studies')}"><div><h2>${t('studies')}</h2><p>${t('studyIntro')}</p></div>${icon('arrow')}</a></div><p class="intro-note">${t('integrationDesc')} ${link('appendices/api-integration',t('availability'))}</p></div>`;
}
function wiki(){return publicationList(['glossary','bibliography'],'reference','referenceIntro');}
function sourceRecord(r){
const family=recordPath(r).split('/').slice(0,-1).join('/'),familyLabel=recordLabel(r),siblings=corpus.records.filter(s=>s.kind===r.kind);
const cited='Pavel Valentov. '+r.title+'. Knowledge Contract Arcana, edition '+corpus.publication.edition+'.';
return `<div class="container source-record publication-record"><div class="page-head"><nav class="breadcrumb" aria-label="Breadcrumb">${link('',t('home'),'','')}<span>/</span>${link(family,familyLabel,'','')}</nav><div class="metadata"><span>${familyLabel}</span><span>${t('publicationEdition')} ${esc(corpus.publication.edition)}</span></div><h1 id="${esc(r.title_id)}" lang="en">${esc(r.title)}</h1><p class="lead" lang="en">${esc(r.summary)}</p><div class="provenance metadata"><span>Pavel Valentov</span><span>CC BY 4.0</span><span>${t('englishText')}</span></div><div class="actions"><a class="text-link" href="${r.source}" target="_blank" rel="noopener">${t('fullSource')}${icon('external')}</a><a class="text-link" href="${r.history}" target="_blank" rel="noopener">${t('history')}${icon('external')}</a></div><p class="reading-language-note">${t('readingNotice')}</p></div>
<div class="source-reading"><article><div class="source-body prose" lang="en">${r.html}</div><section class="document-citation" aria-label="Citation"><h2>${t('citation')}</h2><p lang="en">${esc(cited)} <a href="https://contract.place${r.route}">https://contract.place${r.route}</a>. Source revision <code>${r.revision}</code>.</p><p>${t('sourceCredit')}</p></section></article><aside class="article-aside"><details class="reader-contents" open><summary>${t('contents')}</summary><nav aria-label="${t('contents')}">${r.toc.map(h=>`<a class="toc-level-${h.level}" href="#${esc(h.id)}" lang="en">${esc(h.title)}</a>`).join('')}</nav></details><hr><strong>${familyLabel}</strong>${siblings.map(s=>`<a href="${url(recordPath(s))}"${s.id===r.id?' aria-current="page"':''} lang="en">${esc(s.title)}</a>`).join('')}<hr>${link('reference/glossary',t('reference'),'','')}${link('appendices/source-map',t('sourceMap'),'','')}</aside></div></div>`;
}
function compatibilityPage(path){
const record=corpus.records.find(r=>recordPath(r)===corpus.aliases[path]);
if(!record)throw new Error('Compatibility route has no target: '+path);
return `<article class="container reading">${pageHead(t('compatibility'),t('compatibilityText'))}<h2 lang="en">${esc(record.title)}</h2><p lang="en">${esc(record.summary)}</p>${link(recordPath(record),t('readPaper'),'button')}<p>${link('appendices/source-map',t('sourceMap'))}</p></article>`;
}
function repository(){
return `<div class="container">${pageHead(t('repository'),t('repositoryIntro'))}<div class="actions repo-actions"><a class="button" href="https://github.com/Arcanada-one/knowledge-contract/tree/${corpus.publication.commit}" target="_blank" rel="noopener">${t('sourceRepo')}${icon('external')}</a><a class="text-link" href="/publication.json">publication.json</a></div><div class="table-scroll repository-table" role="region" aria-label="${t('repository')}" tabindex="0"><table><thead><tr><th scope="col">${t('article')}</th><th scope="col">${t('sourceStatus')}</th><th scope="col">${t('revision')}</th></tr></thead><tbody>${corpus.records.map(r=>`<tr><td><a href="${url(recordPath(r))}" lang="en">${esc(r.title)}</a></td><td>${recordLabel(r)}</td><td><a href="${r.source}"><code>${r.revision.slice(0,12)}</code></a></td></tr>`).join('')}</tbody></table></div></div>`;
}
function searchItems(q){
const items=[...corpus.records.map(r=>({title:r.title,desc:r.summary+' '+r.id,type:recordLabel(r),path:recordPath(r)})),...corpus.articles.map(a=>({title:a.title,desc:a.description,type:t('journal'),path:'journal/'+a.id})),{title:t('availability'),desc:t('integrationDesc'),type:t('docs'),path:'docs/availability'}];
return items.filter(x=>normalize(x.title+' '+x.desc+' '+x.type).includes(normalize(q)));
}
function readerAlias(path,target){
 const record=corpus.records.find(r=>r.route===target);
 return '<article class="container reading">'+pageHead(t('chooseLanguage'),t('chooseLanguageText'))+'<h2 lang="en">'+esc(record?record.title:'Knowledge Contract publication')+'</h2><a class="button" href="'+target+'">'+t('readPaper')+icon('arrow')+'</a></article>';
}

function render(){
closeDialogs();const parts=location.pathname.split('/').filter(Boolean);const localized=langs.includes(parts[0]);locale=localized?parts.shift():'en';const path=parts.join('/');
document.documentElement.lang=locale;document.querySelector('.skip').textContent=t('skip');document.querySelector('#header').innerHTML=header(path);document.querySelector('#footer').innerHTML=footer();
let html=null,title=null;const record=corpus.records.find(r=>recordPath(r)===path),article=corpus.articles.find(a=>'journal/'+a.id===path);
if(!localized&&corpus.reader_aliases[path]){html=readerAlias(path,corpus.reader_aliases[path]);title=t('chooseLanguage')}
else if(record){html=sourceRecord(record);title=record.title}
else if(corpus.aliases[path]){html=compatibilityPage(path);title=t('compatibility')}
else if(!path){html=home();title=t('heroTitle')}
else if(path==='research'||path==='science'){html=research();title=t('research')}
else if(path==='engineering'||path==='docs'){html=engineering();title=t('docs')}
else if(path==='engineering/specifications'){html=publicationList(['spec'],'specs','specIntro');title=t('specs')}
else if(path==='engineering/studies'){html=publicationList(['study'],'studies','studyIntro');title=t('studies')}
else if(path==='reference'||path==='wiki'){html=wiki();title=t('reference')}
else if(path==='appendices'){html=publicationList(['appendix'],'appendices','appendixIntro');title=t('appendices')}
else if(path==='pipeline'){html=pipeline();title=t('pipeline')}
else if(path==='books'){html=books();title=t('books')}
else if(path==='repository'){html=repository();title=t('repository')}
else if(path==='journal'){html=journal();title=t('journal')}
else if(article){html=publication(article);title=article.title}
else if(path==='journal/building-a-place'){html=publication(corpus.articles[0]);title=corpus.articles[0].title}
else if(path==='docs/availability'){html=docs(path);title=t('availability')}
else if(path==='search'){html=searchPage();title=t('search')}
else if(path==='about'){html=about();title=t('licensing')}
else if(path==='references'){html=referencesPage();title=t('references')}
else if(path.startsWith('research/')&&refs.find(r=>r.id===parts[1])){const r=refs.find(r=>r.id===parts[1]);html=researchDetail(r);title=r.name}
else{html=`<div class="container">${pageHead('404',t('notFound'))}${link('',t('backHome'),'button')}</div>`;title='404'}
document.querySelector('#main').innerHTML=html;document.title=title+' — contract.place';document.querySelector('meta[name="description"]').content=record?record.summary:t('heroDesc');
bindFilters();bindLanguagePickers();if(path==='search'&&window.KcpSearch&&window.KcpSearch.mount)window.KcpSearch.mount(document);
document.querySelectorAll('.nav-item').forEach(n=>{if(n.getAttribute('href')===url(path.split('/')[0]))n.setAttribute('aria-current','page')});
}


function changeLocale(next){if(!langs.includes(next))return;const parts=location.pathname.split('/').filter(Boolean);if(langs.includes(parts[0]))parts.shift();try{localStorage.setItem('cp-locale',next)}catch{}navigate('/'+next+'/'+(parts.length?parts.join('/')+'/':'')+location.search+location.hash)}
function bindLanguagePickers(scope=document){scope.querySelectorAll('.language-picker').forEach(picker=>{picker.addEventListener('toggle',()=>{if(picker.open)document.querySelectorAll('details[open]').forEach(other=>{if(other!==picker)other.open=false})});picker.addEventListener('focusout',()=>setTimeout(()=>{if(!picker.contains(document.activeElement))picker.open=false},0));picker.addEventListener('keydown',e=>{const options=[...picker.querySelectorAll('.locale-option')];const active=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();picker.open=true;let index=e.key==='Home'?0:e.key==='End'?options.length-1:active<0?(e.key==='ArrowUp'?options.length-1:0):(active+(e.key==='ArrowUp'?-1:1)+options.length)%options.length;options[index].focus()}})});scope.querySelectorAll('.nav-group').forEach(group=>group.addEventListener('toggle',()=>{if(group.open)document.querySelectorAll('.language-picker[open]').forEach(p=>p.open=false)}))}
if(location.pathname==='/'){let saved='en';try{saved=localStorage.getItem('cp-locale')||'en'}catch{}history.replaceState({},'','/'+(langs.includes(saved)?saved:'en')+'/'+location.search+location.hash)}render();
